SELECT clock_timestamp() AS db_at,p.id AS product_id,coalesce((SELECT sum(b.quantity) FROM inventory_balances b WHERE b.tenant_id=p.tenant_id AND b.product_id=p.id),0) AS balances_quantity,coalesce((SELECT sum(m.quantity_delta) FROM inventory_movements m WHERE m.tenant_id=p.tenant_id AND m.product_id=p.id),0) AS all_movement_delta,(SELECT min(o.created_at) FROM fbs_orders o JOIN fbs_order_products q ON q.order_id=o.id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon' AND q.product_id=p.id) AS first_target_order_at FROM products p WHERE p.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND p.id IN (SELECT DISTINCT p.product_id FROM fbs_order_products p JOIN fbs_orders o ON o.id=p.order_id WHERE o.tenant_id='b80a893b-ab87-42b6-8fd7-6d41502c900f' AND o.supply_id='b82d1e9a-30d2-4d7b-b52d-9775c3d266e3' AND o.seller_id='cf6d31c5-944b-4382-af34-636ca9aa8cc3' AND o.marketplace='ozon') ORDER BY p.id LIMIT 20
